import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

transposed_conv1d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// A naive transposed convolution 1D kernel.
// input shape:  (batch_size, in_channels, in_len)
// weight shape: (in_channels, out_channels, kernel_size)
// bias shape:   (out_channels) if has_bias = true
// output shape: (batch_size, out_channels, out_len)
// where out_len = (in_len - 1) * stride - 2*padding + dilation * (kernel_size - 1) + 1

__global__ void transposed_conv1d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int in_len,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool has_bias,
    int out_len
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * out_len;
    if (idx >= total) return;

    // Decompose idx into (b, oc, out_pos)
    int b = idx / (out_channels * out_len);
    int r = idx % (out_channels * out_len);
    int oc = r / out_len;
    int out_pos = r % out_len;

    float val = 0.0f;
    // Calculate the transposed convolution sum
    for (int ic = 0; ic < in_channels; ic++) {
        for (int k = 0; k < kernel_size; k++) {
            // Mapping out_pos back to the corresponding input position
            int in_idx = out_pos - (k * dilation) + padding;
            // We only aggregate if in_idx is divisible by stride
            if (in_idx % stride == 0) {
                int in_pos = in_idx / stride;
                if (in_pos >= 0 && in_pos < in_len) {
                    // input index
                    float inp_val = input[b * in_channels * in_len +
                                          ic * in_len +
                                          in_pos];
                    // weight index
                    float w_val = weight[ic * out_channels * kernel_size +
                                         oc * kernel_size +
                                         k];
                    val += inp_val * w_val;
                }
            }
        }
    }
    // Add bias if needed
    if (has_bias) {
        val += bias[oc];
    }
    // Write to output
    output[b * out_channels * out_len + oc * out_len + out_pos] = val;
}

torch::Tensor transposed_conv1d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int stride,
    int padding,
    int dilation
) {
    // Shapes
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_len = input.size(2);
    int kernel_size = weight.size(2);
    int out_channels = weight.size(1);

    // Output length calculation
    int out_len = (in_len - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;

    auto options = input.options();
    auto out = torch::zeros({batch_size, out_channels, out_len}, options);

    // Total threads
    int total = batch_size * out_channels * out_len;
    const int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    transposed_conv1d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_channels,
        in_len,
        out_channels,
        kernel_size,
        stride,
        padding,
        dilation,
        has_bias,
        out_len
    );
    // Ensure CUDA kernel has finished
    cudaDeviceSynchronize();

    return out;
}
"""

transposed_conv1d_cpp_source = r"""
torch::Tensor transposed_conv1d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int stride,
    int padding,
    int dilation
);
"""

transposed_conv1d = load_inline(
    name="transposed_conv1d",
    cpp_sources=transposed_conv1d_cpp_source,
    cuda_sources=transposed_conv1d_source,
    functions=["transposed_conv1d_cuda"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    """
    Optimized transposed 1D convolution using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        # Weight shape for ConvTranspose1d: (in_channels, out_channels, kernel_size)
        self.weight = nn.Parameter(torch.randn(in_channels, out_channels, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            # create a dummy bias to pass to the kernel if needed
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.has_bias:
            return transposed_conv1d.transposed_conv1d_cuda(
                x, self.weight, self.bias,
                True,
                self.stride,
                self.padding,
                self.dilation
            )
        else:
            # if no bias, pass a zero tensor as placeholder
            dummy_bias = torch.zeros(self.out_channels, dtype=x.dtype, device=x.device)
            return transposed_conv1d.transposed_conv1d_cuda(
                x, self.weight, dummy_bias,
                False,
                self.stride,
                self.padding,
                self.dilation
            )
